using System.Globalization;
using System.Text.Json;
using System.Text.Json.Serialization;
using TradeRecon.Domain.Audit;

namespace TradeRecon.Application.Audit;

/// <summary>
/// Converts audit entries to and from the single-line JSON form used by the append-only trail
/// file. Line-delimited JSON keeps the store genuinely append-only: writing a new entry never
/// rewrites an existing byte.
/// </summary>
public static class AuditEntrySerializer
{
    private static readonly JsonSerializerOptions Options = new()
    {
        WriteIndented = false,
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
        DefaultIgnoreCondition = JsonIgnoreCondition.Never
    };

    /// <summary>Serialises <paramref name="entry"/> as one JSON line (no trailing newline).</summary>
    public static string Serialize(AuditEntry entry)
    {
        ArgumentNullException.ThrowIfNull(entry);
        return JsonSerializer.Serialize(ToDocument(entry), Options);
    }

    /// <summary>Parses one JSON line back into an entry.</summary>
    public static AuditEntry Deserialize(string line)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(line);

        var document = JsonSerializer.Deserialize<AuditEntryDocument>(line, Options)
            ?? throw new FormatException("Audit trail line is not a JSON object.");

        return FromDocument(document);
    }

    /// <summary>Wire projection of an entry. Dates and instants are invariant strings.</summary>
    public static AuditEntryDocument ToDocument(AuditEntry entry)
    {
        ArgumentNullException.ThrowIfNull(entry);

        return new AuditEntryDocument
        {
            Sequence = entry.Sequence,
            Version = entry.Version,
            RequestId = entry.RequestId,
            Action = entry.Action.ToString(),
            Actor = entry.Actor,
            ActorRole = entry.ActorRole.ToString(),
            Proposer = entry.Proposer,
            Checker = entry.Checker,
            BusinessDate = entry.BusinessDate.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture),
            Timestamp = entry.Timestamp.ToUniversalTime().ToString("O", CultureInfo.InvariantCulture),
            ReasonRedacted = entry.ReasonRedacted,
            ReasonHash = entry.ReasonHash,
            EvidenceRedacted = entry.EvidenceRedacted,
            EvidenceHash = entry.EvidenceHash,
            PreviousHash = entry.PreviousHash,
            EntryHash = entry.EntryHash
        };
    }

    private static AuditEntry FromDocument(AuditEntryDocument document)
    {
        return new AuditEntry
        {
            Sequence = document.Sequence,
            Version = document.Version,
            RequestId = document.RequestId,
            Action = Enum.Parse<ResolutionAction>(document.Action, ignoreCase: false),
            Actor = document.Actor,
            ActorRole = Enum.Parse<ActorRole>(document.ActorRole, ignoreCase: false),
            Proposer = document.Proposer,
            Checker = string.IsNullOrEmpty(document.Checker) ? null : document.Checker,
            BusinessDate = DateOnly.ParseExact(document.BusinessDate, "yyyy-MM-dd", CultureInfo.InvariantCulture),
            Timestamp = DateTimeOffset.Parse(document.Timestamp, CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind),
            ReasonRedacted = document.ReasonRedacted,
            ReasonHash = document.ReasonHash,
            EvidenceRedacted = document.EvidenceRedacted,
            EvidenceHash = document.EvidenceHash,
            PreviousHash = document.PreviousHash,
            EntryHash = document.EntryHash
        };
    }
}

/// <summary>Serialisation shape of an audit entry, shared by the trail file and the export.</summary>
public sealed record AuditEntryDocument
{
    public required long Sequence { get; init; }
    public required int Version { get; init; }
    public required string RequestId { get; init; }
    public required string Action { get; init; }
    public required string Actor { get; init; }
    public required string ActorRole { get; init; }
    public required string Proposer { get; init; }
    public string? Checker { get; init; }
    public required string BusinessDate { get; init; }
    public required string Timestamp { get; init; }
    public required string ReasonRedacted { get; init; }
    public required string ReasonHash { get; init; }
    public required string EvidenceRedacted { get; init; }
    public required string EvidenceHash { get; init; }
    public required string PreviousHash { get; init; }
    public required string EntryHash { get; init; }
}

using TradeRecon.Domain.Audit;

namespace TradeRecon.Application.Audit;

/// <summary>
/// An immutable, hash-verified view of the whole audit trail as read from durable storage.
/// </summary>
public sealed class AuditTrailSnapshot
{
    private AuditTrailSnapshot(IReadOnlyList<AuditEntry> entries, bool chainVerified, string headHash)
    {
        Entries = entries;
        ChainVerified = chainVerified;
        HeadHash = headHash;
    }

    /// <summary>Entries in durable append order.</summary>
    public IReadOnlyList<AuditEntry> Entries { get; }

    /// <summary>False when a hash, link or sequence number does not reconcile.</summary>
    public bool ChainVerified { get; }

    /// <summary>Hash of the last entry, or the genesis hash for an empty trail.</summary>
    public string HeadHash { get; }

    /// <summary>Sequence number the next appended entry must take.</summary>
    public long NextSequence => Entries.Count == 0 ? 1 : Entries[^1].Sequence + 1;

    /// <summary>Builds a snapshot, recomputing the hash chain to detect tampering.</summary>
    public static AuditTrailSnapshot Create(IReadOnlyList<AuditEntry> entries)
    {
        ArgumentNullException.ThrowIfNull(entries);

        var verified = true;
        var previous = AuditHashing.GenesisHash;
        var expectedSequence = 1L;

        foreach (var entry in entries)
        {
            if (entry.Sequence != expectedSequence
                || !string.Equals(entry.PreviousHash, previous, StringComparison.Ordinal)
                || !AuditHashing.HasValidHash(entry))
            {
                verified = false;
            }

            previous = entry.EntryHash;
            expectedSequence++;
        }

        return new AuditTrailSnapshot(entries, verified, previous);
    }

    /// <summary>All entries for a request, in append order.</summary>
    public IReadOnlyList<AuditEntry> EntriesFor(string requestId)
        => Entries.Where(e => ResolutionIdentity.SameRequest(e.RequestId, requestId)).ToList();

    /// <summary>The proposal entry for a request, or <c>null</c> when it was never proposed.</summary>
    public AuditEntry? ProposalFor(string requestId)
        => Entries.FirstOrDefault(e =>
            e.Action == ResolutionAction.Proposed && ResolutionIdentity.SameRequest(e.RequestId, requestId));

    /// <summary>The single durable final decision for a request, or <c>null</c> when still pending.</summary>
    public AuditEntry? DecisionFor(string requestId)
        => Entries.FirstOrDefault(e =>
            e.Action != ResolutionAction.Proposed && ResolutionIdentity.SameRequest(e.RequestId, requestId));
}

namespace TradeRecon.Application.Audit;

/// <summary>
/// Comparison rules for the identities the workflow recognises. Request ids and person ids are
/// compared case-insensitively after trimming so that a retry sent as <c>"Alice"</c> cannot be
/// mistaken for a second, distinct person <c>"alice "</c> — which would otherwise defeat both
/// idempotency and the self-approval guard.
/// </summary>
public static class ResolutionIdentity
{
    /// <summary>Canonical form of a supplied identity or request id.</summary>
    public static string Normalize(string? value) => (value ?? string.Empty).Trim();

    /// <summary>True when both values name the same request.</summary>
    public static bool SameRequest(string? left, string? right)
        => string.Equals(Normalize(left), Normalize(right), StringComparison.OrdinalIgnoreCase);

    /// <summary>True when both values name the same person.</summary>
    public static bool SamePerson(string? left, string? right)
        => string.Equals(Normalize(left), Normalize(right), StringComparison.OrdinalIgnoreCase);
}

using TradeRecon.Application.Audit;
using TradeRecon.Domain.Audit;

namespace TradeRecon.Application.Abstractions;

/// <summary>
/// Durable, append-only storage for the resolution audit trail.
///
/// Implementations must serialise <see cref="ExecuteAsync{TResult}"/> across every concurrent
/// caller — including separate operating-system processes — so that a decision is evaluated
/// against, and appended to, a trail that cannot change underneath it. That is what makes two
/// racing decisions collapse to exactly one durable final decision.
/// </summary>
public interface IAuditTrailStore
{
    /// <summary>Creates the trail if it does not exist. Safe to call repeatedly.</summary>
    Task InitializeAsync(CancellationToken cancellationToken = default);

    /// <summary>Reads and hash-verifies the whole trail.</summary>
    Task<AuditTrailSnapshot> ReadAsync(CancellationToken cancellationToken = default);

    /// <summary>
    /// Runs <paramref name="decide"/> under an exclusive lock over the trail and durably appends
    /// the entry it returns, if any, before releasing the lock.
    /// </summary>
    Task<TResult> ExecuteAsync<TResult>(
        Func<AuditTrailSnapshot, AuditTransaction<TResult>> decide,
        CancellationToken cancellationToken = default);
}

/// <summary>The outcome of a guarded decision: an optional entry to append plus its result.</summary>
/// <param name="Append">Entry to append durably, or <c>null</c> for a read-only outcome.</param>
/// <param name="Result">Value returned to the caller.</param>
public sealed record AuditTransaction<TResult>(AuditEntry? Append, TResult Result);

