1. using System.Globalization;
2. using Microsoft.Extensions.DependencyInjection;
3. using TradeRecon.Application.Audit;
4. using TradeRecon.Domain.Audit;
5. using TradeRecon.Infrastructure;
6. 
7. namespace TradeRecon.AuditConsole;
8. 
9. /// <summary>
10. /// Black-box command-line host for explainable exception resolution and its audit history.
11. ///
12. /// Four verbs, each writing one JSON document to stdout and nothing else:
13. ///
14. /// <code>
15. /// initialize --state &lt;dir&gt;
16. /// propose    --state &lt;dir&gt; --request-id &lt;id&gt; --proposer &lt;who&gt; --business-date &lt;yyyy-MM-dd&gt;
17. ///            --reason &lt;text&gt; --evidence &lt;text&gt;
18. /// decide     --state &lt;dir&gt; --request-id &lt;id&gt; --approver &lt;who&gt; --decision &lt;approve|reject&gt;
19. /// export     --state &lt;dir&gt; --from &lt;yyyy-MM-dd&gt; --to &lt;yyyy-MM-dd&gt; --output &lt;path&gt;
20. /// </code>
21. ///
22. /// Exit codes: 0 accepted (including an idempotent retry), 3 refused by policy (self-approval,
23. /// an already-decided request, a conflicting proposal, an unknown request), 1 invalid arguments
24. /// or an I/O failure. A refusal still writes a JSON document describing why.
25. ///
26. /// Caller-supplied reason and evidence text is redacted before it reaches stdout, stderr or
27. /// durable state, so account identifiers and trade amounts cannot leak through this host.
28. /// </summary>
29. public static class Program
30. {
31.     /// <summary>The command was accepted, or an identical retry was replayed.</summary>
32.     public const int ExitOk = 0;
33. 
34.     /// <summary>Invalid arguments or an I/O failure.</summary>
35.     public const int ExitError = 1;
36. 
37.     /// <summary>The command was understood but refused by a workflow rule.</summary>
38.     public const int ExitRefused = 3;
39. 
40.     private const string Usage = """
41.         Usage:
42.           TradeRecon.AuditConsole initialize --state <dir>
43.           TradeRecon.AuditConsole propose    --state <dir> --request-id <id> --proposer <who>
44.                                              --business-date <yyyy-MM-dd> --reason <text> --evidence <text>
45.           TradeRecon.AuditConsole decide     --state <dir> --request-id <id> --approver <who>
46.                                              --decision <approve|reject>
47.           TradeRecon.AuditConsole export     --state <dir> --from <yyyy-MM-dd> --to <yyyy-MM-dd>
48.                                              --output <path>
49.         """;
50. 
51.     public static Task<int> Main(string[] args)
52.         => RunAsync(args, System.Console.Out, System.Console.Error);
53. 
54.     /// <summary>Entry point with injectable streams so the CLI contract is directly testable.</summary>
55.     public static async Task<int> RunAsync(string[] args, TextWriter stdout, TextWriter stderr)
56.     {
57.         ArgumentNullException.ThrowIfNull(args);
58.         ArgumentNullException.ThrowIfNull(stdout);
59.         ArgumentNullException.ThrowIfNull(stderr);
60. 
61.         if (args.Length == 0 || args.Contains("--help") || args.Contains("-h"))
62.         {
63.             await stdout.WriteLineAsync(Usage).ConfigureAwait(false);
64.             return args.Length == 0 ? ExitError : ExitOk;
65.         }
66. 
67.         AuditCliCommand command;
68.         try
69.         {
70.             command = AuditCliCommand.Parse(args);
71.         }
72.         catch (ArgumentException ex)
73.         {
74.             return await FailAsync(stdout, stderr, ex.Message).ConfigureAwait(false);
75.         }
76. 
77.         try
78.         {
79.             return await DispatchAsync(command, stdout, stderr).ConfigureAwait(false);
80.         }
81.         catch (ArgumentException ex)
82.         {
83.             return await FailAsync(stdout, stderr, ex.Message).ConfigureAwait(false);
84.         }
85.         catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or TimeoutException or InvalidOperationException)
86.         {
87.             return await FailAsync(stdout, stderr, $"Audit state is unavailable: {ex.GetType().Name}.").ConfigureAwait(false);
88.         }
89.     }
90. 
91.     private static async Task<int> DispatchAsync(AuditCliCommand command, TextWriter stdout, TextWriter stderr)
92.     {
93.         var services = new ServiceCollection();
94.         services.AddTradeReconAudit(command.RequireOption("state", "state-directory", "state-dir"));
95. 
96.         await using var provider = services.BuildServiceProvider();
97.         var workflow = provider.GetRequiredService<ResolutionWorkflowService>();
98. 
99.         switch (command.Verb)
100.         {
101.             case "initialize":
102.                 return await WriteResultAsync(stdout, stderr, command.Verb, await workflow.InitializeAsync().ConfigureAwait(false)).ConfigureAwait(false);
103. 
104.             case "propose":
105.             {
106.                 var result = await workflow.ProposeAsync(new ProposeCommand
107.                 {
108.                     RequestId = command.RequireOption("request-id", "request", "id"),
109.                     Proposer = command.RequireOption("proposer", "maker"),
110.                     BusinessDate = ParseDate(command.RequireOption("business-date", "date"), "--business-date"),
111.                     Reason = command.RequireOption("reason"),
112.                     Evidence = command.RequireOption("evidence")
113.                 }).ConfigureAwait(false);
114. 
115.                 return await WriteResultAsync(stdout, stderr, command.Verb, result).ConfigureAwait(false);
116.             }
117. 
118.             case "decide":
119.             {
120.                 var raw = command.RequireOption("decision", "outcome");
121.                 if (!TryParseDecision(raw, out var decision))
122.                 {
123.                     var refusal = new WorkflowResult
124.                     {
125.                         Ok = false,
126.                         Outcome = WorkflowOutcome.InvalidDecision,
127.                         Error = WorkflowOutcome.InvalidDecision,
128.                         RequestId = command.RequireOption("request-id", "request", "id"),
129.                         IdempotentReplay = false,
130.                         Message = "The decision must be either approve or reject."
131.                     };
132. 
133.                     return await WriteResultAsync(stdout, stderr, command.Verb, refusal).ConfigureAwait(false);
134.                 }
135. 
136.                 var result = await workflow.DecideAsync(new DecideCommand
137.                 {
138.                     RequestId = command.RequireOption("request-id", "request", "id"),
139.                     Approver = command.RequireOption("approver", "checker", "decider"),
140.                     Decision = decision
141.                 }).ConfigureAwait(false);
142. 
143.                 return await WriteResultAsync(stdout, stderr, command.Verb, result).ConfigureAwait(false);
144.             }
145. 
146.             case "export":
147.             {
148.                 var from = ParseDate(command.RequireOption("from", "from-date"), "--from");
149.                 var to = ParseDate(command.RequireOption("to", "to-date"), "--to");
150.                 if (to < from)
151.                 {
152.                     throw new ArgumentException("The --to date precedes the --from date.");
153.                 }
154. 
155.                 var exportPath = Path.GetFullPath(command.RequireOption("output", "export-path", "out"));
156.                 var export = await workflow.ExportAsync(from, to).ConfigureAwait(false);
157.                 var json = AuditJson.Serialize(export);
158. 
159.                 var directory = Path.GetDirectoryName(exportPath);
160.                 if (!string.IsNullOrEmpty(directory))
161.                 {
162.                     Directory.CreateDirectory(directory);
163.                 }
164. 
165.                 await File.WriteAllTextAsync(exportPath, json + "\n").ConfigureAwait(false);
166.                 await stdout.WriteLineAsync(json).ConfigureAwait(false);
167.                 return ExitOk;
168.             }
169. 
170.             default:
171.                 return await FailAsync(stdout, stderr, $"Unknown command '{command.Verb}'.").ConfigureAwait(false);
172.         }
173.     }
174. 
175.     private static async Task<int> WriteResultAsync(
176.         TextWriter stdout,
177.         TextWriter stderr,
178.         string verb,
179.         WorkflowResult result)
180.     {
181.         await stdout.WriteLineAsync(AuditJson.Serialize(new AuditCommandResponse
182.         {
183.             SchemaVersion = AuditExportBuilder.SchemaVersion,
184.             Command = verb,
185.             Result = result
186.         })).ConfigureAwait(false);
187. 
188.         if (result.Ok)
189.         {
190.             return ExitOk;
191.         }
192. 
193.         await stderr.WriteLineAsync($"{verb}: refused ({result.Outcome}).").ConfigureAwait(false);
194.         return ExitRefused;
195.     }
196. 
197.     private static async Task<int> FailAsync(TextWriter stdout, TextWriter stderr, string message)
198.     {
199.         await stdout.WriteLineAsync(AuditJson.Serialize(new AuditCommandResponse
200.         {
201.             SchemaVersion = AuditExportBuilder.SchemaVersion,
202.             Command = "unknown",
203.             Result = new WorkflowResult
204.             {
205.                 Ok = false,
206.                 Outcome = "invalid-arguments",
207.                 Error = "invalid-arguments",
208.                 IdempotentReplay = false,
209.                 Message = message
210.             }
211.         })).ConfigureAwait(false);
212. 
213.         await stderr.WriteLineAsync(message).ConfigureAwait(false);
214.         await stderr.WriteLineAsync(Usage).ConfigureAwait(false);
215.         return ExitError;
216.     }
217. 
218.     private static DateOnly ParseDate(string value, string option)
219.     {
220.         if (DateOnly.TryParseExact(value, "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out var date))
221.         {
222.             return date;
223.         }
224. 
225.         if (DateTimeOffset.TryParse(value, CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind, out var instant))
226.         {
227.             return DateOnly.FromDateTime(instant.UtcDateTime);
228.         }
229. 
230.         throw new ArgumentException($"Option {option} requires an ISO date (yyyy-MM-dd).");
231.     }
232. 
233.     private static bool TryParseDecision(string value, out ResolutionAction decision)
234.     {
235.         switch (value.Trim().ToLowerInvariant())
236.         {
237.             case "approve":
238.             case "approved":
239.             case "accept":
240.             case "accepted":
241.                 decision = ResolutionAction.Approved;
242.                 return true;
243. 
244.             case "reject":
245.             case "rejected":
246.             case "decline":
247.             case "declined":
248.             case "deny":
249.             case "denied":
250.                 decision = ResolutionAction.Rejected;
251.                 return true;
252. 
253.             default:
254.                 decision = ResolutionAction.Proposed;
255.                 return false;
256.         }
257.     }
